'use strict';
(() => {
  const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const projects=window.PORTFOLIO_PROJECTS;
  const moving=()=>!matchMedia('(prefers-reduced-motion:reduce)').matches&&!document.documentElement.classList.contains('no-motion');
  const animate=el=>{if(moving()&&el.animate)el.animate([{opacity:.7,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:260,easing:'ease-out'});};
  const years=[
    {year:'2023',label:'Start with curiosity',chapter:'FOUNDATIONS',copy:'Began AI Engineering at Xiamen University Malaysia and joined the people behind campus activities.',events:[['AI Engineering · XMUM','Undergraduate programme, September 2023–September 2027 (expected).'],['AIESEC XMUM','General Affairs, 2023–2024; followed by Assistant, General Affairs, 2024–2025.']],credential:'aiesec'},
    {year:'2024',label:'Build the foundations',chapter:'FIRST APPLICATIONS',copy:'Connected classroom foundations to an educational AI application and earned academic recognition.',events:[['NeuroInsight','Explored MRI and clinical-data classification in an educational project.'],["Dean’s List",'Recognized for the September 2024 academic session.']],project:'mri',credential:'deans-list'},
    {year:'2025',label:'Models, teams & responsibility',chapter:'VISION & LEADERSHIP',copy:'Worked on facial expression recognition and residual classification while taking on campus leadership responsibilities.',events:[['FER2013 & Res UCN','Compared facial-expression classifiers and contributed Quinsh to the group’s Res UCN architecture.'],['XMUM AI Club','Head of General Affairs, managing RM1,000 of WPS sponsorship and booking venues for a national AI tournament.']],project:'resucn',credential:'ai-club'},
    {year:'2026',label:'Research becomes a working system',chapter:'RESEARCH → APPLICATIONS',copy:'From efficient detectors to evidence-grounded inspection workflows, with experiments and interfaces that others can explore.',events:[['PaddyLiteX & MarineLite','Lightweight detection research, model comparisons and ablation studies.'],['DefectRAG','Visual anomaly inspection, cited RAG, Supabase corrective-action tracking and n8n hosted on AWS Lightsail with Docker Compose and Caddy HTTPS.'],['dPickleball','Contributed to the team that placed 2nd among 13 teams.']],project:'defectrag',credential:'love-in-action'},
    {year:'2027',label:'The next chapter',chapter:'PLANNED · INTERNSHIP',copy:'Seeking an AI/ML internship (computer vision, deep learning, generative AI) starting 29 March 2027, for 3–5 months.',events:[['Apply research in a team','Malaysia preferred; interested in practical vision and AI engineering work.'],['Expected graduation','September 2027 · Xiamen University Malaysia.']],planned:true}
  ];
  const milestones=$('#milestones'),old=milestones?.querySelector('.milestone-layout');
  if(old){
    const journey=document.createElement('div');journey.className='way-journey';
    journey.innerHTML='<div class="journey-intro"><span class="project-kicker">TIMELINE</span><h2 id="journey-heading">Timeline</h2><p>Choose a year to explore the work, the learning and the people behind it.</p></div><div class="journey-years" role="tablist" aria-label="Journey years">'+years.map((y,i)=>`<button id="journey-tab-${i}" role="tab" aria-controls="journey-panel" aria-selected="${i===3}" tabindex="${i===3?0:-1}" data-year="${i}">${y.year}<span>${y.planned?'NEXT':'0'+(i+1)}</span></button>`).join('')+'</div><div id="journey-panel" role="tabpanel" tabindex="0"></div>';
    milestones.setAttribute("aria-labelledby","journey-heading");
    old.before(journey);const archive=document.createElement('details');archive.className='journey-archive';archive.innerHTML='<summary>All achievements & certificates <span aria-hidden="true">＋</span></summary>';old.before(archive);archive.append(old);
    function selectYear(i,focus=false){
      const y=years[i],p=projects.find(p=>p.id===y.project),m=p&&window.projectMedia(p.id);
      const certificate=window.PORTFOLIO_CREDENTIALS?.items.find(c=>c.id===y.credential&&c.attachments?.length);
      const panel=journey.querySelector('#journey-panel');panel.setAttribute('aria-labelledby','journey-tab-'+i);
      panel.innerHTML=`<div class="journey-chapter"><span class="journey-numeral" aria-hidden="true">${y.year.slice(2)}</span><span class="project-kicker">${y.chapter}</span><h3>${esc(y.label)}</h3><p>${esc(y.copy)}</p><div class="journey-actions">${certificate?`<button data-credential="${certificate.id}">${esc(certificate.title)} · Certificate ↗</button>`:''}${y.planned?'<a href="#contact">Let’s work together ↗</a>':''}</div></div><div class="journey-evidence">${y.events.map(([title,copy])=>`<article><span class="journey-dot" aria-hidden="true"></span><h4>${esc(title)}</h4><p>${esc(copy)}</p></article>`).join('')}${p?`<button class="journey-project" data-project="${p.id}"><img src="${esc(m.file)}" alt="${esc(m.alt)}" loading="lazy"><span>Explore the work<strong>${esc(p.short)} ↗</strong></span></button>`:'<div class="journey-signature">Observation <span>→</span> Experiment <span>→</span> Application</div>'}</div>`;
      journey.querySelectorAll('[data-year]').forEach((b,n)=>{b.setAttribute('aria-selected',String(n===i));b.tabIndex=n===i?0:-1;if(focus&&n===i)b.focus();});animate(panel);
    }
    journey.addEventListener('click',e=>{const b=e.target.closest('[data-year]');if(b)selectYear(+b.dataset.year);});
    journey.querySelector('[role=tablist]').addEventListener('keydown',e=>{const b=e.target.closest('[data-year]');if(!b)return;let i=+b.dataset.year;if(e.key==='ArrowRight')i=(i+1)%years.length;else if(e.key==='ArrowLeft')i=(i+years.length-1)%years.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=years.length-1;else return;e.preventDefault();selectYear(i,true);});selectYear(3);
  }

  // Curated entry points use the existing search/filter system, so they compose with it.
  const toolbar=$('.projects-toolbar');
  if(toolbar){const guide=document.createElement('div');guide.className='project-paths';guide.innerHTML='<div><span class="project-kicker">FILTER BY TOPIC</span><p>Which topic interests you?</p></div><div class="path-buttons" role="group" aria-label="Explore projects by interest">'+[['All projects',''],['Efficient vision','detection'],['Generative AI','RAG'],['Automation','n8n'],['Agent learning','PPO']].map(([label,q],i)=>`<button data-path="${q}" aria-pressed="${i===0}">${label}<span aria-hidden="true">↗</span></button>`).join('')+'</div><p class="path-context" aria-live="polite">Pick a topic, then open a case study to see the evidence.</p>';toolbar.before(guide);
    const search=$('#project-search');function sync(){guide.querySelectorAll('[data-path]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.path===search.value)));}
    guide.addEventListener('click',e=>{const b=e.target.closest('[data-path]');if(!b)return;$('#reset-search').click();search.value=b.dataset.path;search.dispatchEvent(new Event('input',{bubbles:true}));const count=document.querySelectorAll('.project-card:not([hidden])').length;guide.querySelector('.path-context').textContent=`${count} ${count===1?'project':'projects'} to explore · ${b.textContent.replace('↗','').trim()}`;});search.addEventListener('input',sync);$('#reset-search').addEventListener('click',sync);
  }

  const stages=[['Inspect','DINOv2','Frozen visual features and normal-reference memory banks produce anomaly scores and coarse localization heatmaps. Scores are feature distances, not defect probabilities.'],['Ground','LangChain · LangGraph · Qwen','Retrieve relevant document passages, route the question and generate an explanation with checked source citations. The assistant does not visually inspect the uploaded image.'],['Review','React · FastAPI · Supabase','Connect inspection measurements to case history, human review records and corrective-action tracking. Human review decisions remain separate from the model verdict.'],['Automate','n8n · AWS Lightsail · Docker Compose · Caddy','Validate case events, check authorization, notify supervisors and record delivery receipts. The n8n deployment runs on AWS Lightsail using Docker Compose, behind a Caddy reverse proxy with HTTPS. Visual inference and RAG remain separate from workflow automation.']];
  function enhanceReader(){
    const id=window.PortfolioReader?.current();if(id!=='defectrag'||$('#defect-workflow'))return;
    const section=$('#story-work');if(!section)return;
    const flow=document.createElement('div');flow.id='defect-workflow';flow.className='defect-workflow';
    flow.innerHTML='<span class="project-kicker">HOW THE SYSTEM CONNECTS</span><h4>Follow one inspection.</h4><div class="workflow-tabs" role="tablist" aria-label="DefectRAG workflow">'+stages.map(([name],i)=>`<button role="tab" id="workflow-tab-${i}" aria-controls="workflow-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-stage="${i}"><small>0${i+1}</small>${name}</button>`).join('')+'</div><div id="workflow-panel" class="workflow-panel" role="tabpanel" tabindex="0"></div>';
    section.append(flow);function select(i,focus=false){const [name,tech,copy]=stages[i];const panel=flow.querySelector('#workflow-panel');panel.setAttribute('aria-labelledby','workflow-tab-'+i);panel.innerHTML=`<span>${esc(tech)}</span><h5>${esc(name)}</h5><p>${esc(copy)}</p>`;flow.querySelectorAll('[data-stage]').forEach((b,n)=>{b.setAttribute('aria-selected',String(i===n));b.tabIndex=i===n?0:-1;if(focus&&i===n)b.focus();});animate(panel);}
    flow.addEventListener('click',e=>{const b=e.target.closest('[data-stage]');if(b)select(+b.dataset.stage);});flow.addEventListener('keydown',e=>{const b=e.target.closest('[data-stage]');if(!b)return;let i=+b.dataset.stage;if(e.key==='ArrowRight')i=(i+1)%4;else if(e.key==='ArrowLeft')i=(i+3)%4;else if(e.key==='Home')i=0;else if(e.key==='End')i=3;else return;e.preventDefault();select(i,true);});select(0);
  }
  const reader=$('#dialog-content');if(reader)new MutationObserver(enhanceReader).observe(reader,{childList:true});enhanceReader();

  // Readable screenshots without leaving the portfolio. This does not alter autoplay settings.
  const lightbox=document.createElement('dialog');lightbox.className='way-lightbox';lightbox.setAttribute('aria-label','Full-size project screenshot');document.body.append(lightbox);let lastFocus=null,images=[],photoIndex=0;
  function showPhoto(i){photoIndex=(i+images.length)%images.length;const m=images[photoIndex];lightbox.innerHTML=`<div class="lightbox-toolbar"><span>${esc(m.label)} · ${photoIndex+1} / ${images.length}</span><button data-lightbox-close aria-label="Close full-size screenshot">Close ×</button></div><img src="${esc(m.file)}" alt="${esc(m.alt)}"><div class="lightbox-bottom"><button data-lightbox-prev aria-label="Previous full-size screenshot">← Previous</button><p>${esc(m.caption||m.label)}</p><button data-lightbox-next aria-label="Next full-size screenshot">Next →</button></div>`;lightbox.querySelector('[data-lightbox-close]').focus({preventScroll:true});}
  function openPhoto(button){const img=$('#story-photo img');if(!img)return;images=Array.from(document.querySelectorAll('[data-story-photo]')).map(b=>window.PortfolioMedia[b.dataset.storyPhoto]).filter(Boolean);if(!images.length)images=[{file:img.getAttribute('src'),alt:img.alt,label:window.PortfolioReader?.current()||'Project screenshot'}];lastFocus=button;const selected=images.findIndex(m=>m.file===img.getAttribute('src'));showPhoto(Math.max(0,selected));lightbox.showModal();lightbox.querySelector('[data-lightbox-close]').focus();}
  function addExpand(){const host=$('#story-photo');if(!host||host.querySelector('.expand-screenshot'))return;const b=document.createElement('button');b.className='expand-screenshot';b.type='button';b.textContent='Expand screenshot ⤢';b.addEventListener('click',()=>openPhoto(b));host.append(b);}
  if(reader)new MutationObserver(addExpand).observe(reader,{childList:true,subtree:true});addExpand();
  lightbox.addEventListener('click',e=>{if(e.target.closest('[data-lightbox-close]')||e.target===lightbox)lightbox.close();else if(e.target.closest('[data-lightbox-prev]'))showPhoto(photoIndex-1);else if(e.target.closest('[data-lightbox-next]'))showPhoto(photoIndex+1);});
  lightbox.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();showPhoto(photoIndex-1);}if(e.key==='ArrowRight'){e.preventDefault();showPhoto(photoIndex+1);}});lightbox.addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});else $('#project-dialog .dialog-close')?.focus();});
})();
